import{z as p,x as d,o as n,c,q as s,j as t,D as r,d as a,s as o,S as E,b as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"unikernel","description":"","frontmatter":{"title":"unikernel","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/unikernel.md","filePath":"cs/unikernel.md","lastUpdated":1791063341000}'),u={name:"cs/unikernel.md"};function A(B,e,k,h,m,f){const l=d("Mermaid");return n(),c("div",null,[e[2]||(e[2]=s('<h1 id="unikernel" tabindex="-1">unikernel <a class="header-anchor" href="#unikernel" aria-label="Permalink to &quot;unikernel&quot;">​</a></h1><div class="epigraph"><p>unikernel 把应用与仅需的库 OS 链成单一地址空间映像：无用户/内核切换，设备是库，部署常在 hypervisor 上当客户。</p><footer>—— 据 Madhavapeddy et al., MirageOS, ASPLOS 2013；[用户内核分裂](/cs/user-kernel-split) 为对照</footer></div><p><a href="/cs/kata-containers">Kata</a> 仍跑完整 Linux。<a href="/cs/firecracker-microvm">Firecracker</a> 客户仍是通用内核。缺口是 <strong>单地址空间库 OS</strong>：unikernel。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无系统调用门：<code>read</code> 是函数。缺口：调试、多进程、Linux ABI 兼容差；安全靠 hypervisor 而非用户/内核。本课不把每个项目（Mirage、IncludeOS、OSv）写成目录。</p><p><span class="marginnote">「库 OS」就是把内核里需要的那一小块功能（协议栈、文件系统）编译成普通库，跟应用链成一个可执行文件——<code>read</code> 不再是系统调用，就是一次函数跳转。</span></p><p><span class="marginnote">语言运行时（OCaml/Rust）常一起裁。对象是链接形态，不是微内核 IPC。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用 + 协议库 + virtio 前端 → 单 ELF → KVM 加载。对照 gVisor：一个模拟 syscall，一个消灭 syscall。对照 <a href="/cs/dpdk-kernel-bypass">DPDK</a>：都在用户（或单空间）处理包。对照 runc：无多进程模型。</p>',9)),(n(),t(E,null,{default:r(()=>[o(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%22%5D%20--%3E%20LIBOS%5B%22%E5%BA%93%20OS%22%5D%0A%20%20LIBOS%20--%3E%20IMG%5B%22%E5%8D%95%E4%B8%80%E6%98%A0%E5%83%8F%22%5D%0A%20%20IMG%20--%3E%20HV%5B%22hypervisor%20%E5%AE%A2%E6%88%B7%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i("h2",{id:"机制",tabindex:"-1"},[a("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=i("p",null,[a("同一次 "),i("code",null,"read"),a("，通用内核与 unikernel 走的路径差在哪：")],-1)),(n(),t(E,null,{default:r(()=>[o(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E5%BA%94%E7%94%A8%E8%B0%83%E7%94%A8%20read%22%5D%20--%3E%20Q%7B%22%E8%B7%91%E5%9C%A8%E5%93%AA%E7%A7%8D%E5%BD%A2%E6%80%81%22%7D%0A%20%20Q%20--%3E%7C%22%E9%80%9A%E7%94%A8%20Linux%22%7C%20TRAP%5B%22%E9%99%B7%E5%85%A5%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%E9%97%A8%22%5D%0A%20%20TRAP%20--%3E%20KRNL%5B%22%E5%86%85%E6%A0%B8%E6%89%A7%E8%A1%8C%EF%BC%8C%E6%A8%A1%E5%BC%8F%E5%88%87%E6%8D%A2%22%5D%0A%20%20KRNL%20--%3E%20RET1%5B%22%E8%BF%94%E5%9B%9E%E7%94%A8%E6%88%B7%E6%80%81%22%5D%0A%20%20Q%20--%3E%7C%22unikernel%22%7C%20DIRECT%5B%22%E7%9B%B4%E6%8E%A5%E5%87%BD%E6%95%B0%E8%B0%83%E7%94%A8%E8%BF%9B%E5%BA%93%20OS%22%5D%0A%20%20DIRECT%20--%3E%20RET2%5B%22%E5%8E%9F%E5%9C%B0%E8%BF%94%E5%9B%9E%EF%BC%8C%E6%97%A0%E6%A8%A1%E5%BC%8F%E5%88%87%E6%8D%A2%22%5D%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=s('<p>unikernel 用链接时裁剪换攻击面与启动，适合专用网关。通用 POSIX 应用难迁。不要写成万能。与 <a href="/cs/linux-capabilities">capabilities</a>：无进程模型则无 cap。与 <a href="/cs/kernel-audit">audit</a>：要自己打日志。</p><p><span class="marginnote">数字实例：传统 Linux 一次 read 要进出内核各一次，陷阱开销约几百纳秒到一微秒；unikernel 里同一调用是直接函数调用（纳秒级），且映像常只有几 MB、毫秒级启动。</span></p><p>一个库漏洞即全部特权，因无用户/内核裂。</p><p>实现上：没有多进程就没有 fork/exec 模型，监控要另做。调试靠 hypervisor 串口。virtio 前端仍常保留，因为部署在 KVM 上。 读法上只引用<a href="/cs/kata-containers">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>unikernel</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 xen mini-os。不保证热更新。下一课微内核：L4/seL4。</p><p>版本字段会变，课序钉的是机制对象「unikernel」，不是某一主线内核的结构体名。 后课默认：应用可与库 OS 链成单映像。IPC 微内核与证明，下一课 seL4。</p><p><span class="marginnote">常见误区：初学者容易把 unikernel 当「更小的 Linux」。它没有多进程、没有 fork/exec，POSIX ABI 常常不兼容；而且用户/内核那道墙整个不存在——一个库漏洞就拥有全部特权，隔离全靠 hypervisor。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>unikernel：单地址空间，syscall 变函数调用。</li><li>靠 hypervisor 隔离多租户。</li><li>微内核 seL4 是下一课。</li><li>出处：MirageOS ASPLOS 2013；库 OS 文献。</li></ul>',12))])}const _=p(u,[["render",A]]);export{D as __pageData,_ as default};
